function createAnnotationsFromIssues(issues) {
    if (issues.length > 0) {
        lib_core.info(`Creating annotations for ${issues.length} issues:`);
    }
    for (const issue of issues) {
        const message = issue.message;
        const properties = {
            title: `${CODE_PUSHUP_UNICODE_LOGO} ${issue.plugin.title} | ${issue.audit.title}`,
            file: issue.source.file,
            startLine: issue.source.position?.startLine,
            startColumn: issue.source.position?.startColumn,
            endLine: issue.source.position?.endLine,
            endColumn: issue.source.position?.endColumn
        };
        switch (issue.severity) {
            case 'error':
                lib_core.error(message, properties);
                break;
            case 'warning':
                lib_core.warning(message, properties);
                break;
            case 'info':
                lib_core.notice(message, properties);
                break;
        }
    }
}

